var ENGINE = _global.getCurrentEngine();
var INTERFACE = _global.getCurrentInterface();
var start_x = 500;
var start_y = 280;
var SHELL = _global.getCurrentShell();
var language;
var localized_frame = 4;
available;
if(SHELL.getLocalizedFrame != undefined)
{
   localized_frame = SHELL.getLocalizedFrame();
}
switch(localized_frame)
{
   case 1:
      language = "english";
      break;
   case 2:
      language = "portuguese";
      break;
   case 3:
      language = "french";
      break;
   case 4:
      language = "spanish";
      break;
   default:
      language = "english";
}
background_mc.bgobjects_mc.changerooms_mc.changeroomshere_mc.gotoAndStop(language);
