background_mc.dressup_mc.gotoAndStop(language);
interface_mc.hair_btn_states.gotoAndStop(language);
interface_mc.clothing_btn_states.gotoAndStop(language);
triggers_mc.town_mc.triggerFunction = function()
{
   ENGINE.sendJoinRoom("town",466,280);
};
triggers_mc.clothing_mc.triggerFunction = function()
{
   INTERFACE.showContent("clothing_catalogue");
};
town_btn_states.town_btn.onRelease = function()
{
   ENGINE.sendPlayerMove(540,233);
};
interface_mc.clothing_btn_states.clothing_btn.onRelease = function()
{
   INTERFACE.showContent("clothing_catalogue");
};
